import { registrationTimeline } from "./registration-timeline";
import { sumAmounts } from "./sum-amounts";
import {
  formatAmount,
  type MemberDeclaration,
  type MemberDetails,
} from "./entity-details";

// https://api.parliament.uk/regnal-years/parliament-periods/59
export const CURRENT_PARLIAMENT_START = "2024-07-09T00:00:00Z";

function earningsTotal(declarations: MemberDeclaration[]) {
  const entries = declarations.flatMap((declaration) => declaration.entries);
  return {
    declarationCount: declarations.length,
    amount: sumAmounts(
      entries.flatMap((entry) =>
        entry.currency === "GBP" && entry.amount !== null ? [entry.amount] : [],
      ),
    ),
    incomplete: entries.some(
      (entry) =>
        !entry.currency?.trim() ||
        (entry.currency === "GBP" && entry.amount === null),
    ),
  };
}

function isEarnings(name: string): boolean {
  const label = name.trim().replace(/\s+/gu, " ").toLowerCase();
  return (
    label === "employment" ||
    label === "employment and earnings" ||
    label === "employment and earnings - ad hoc payments" ||
    label === "employment and earnings - ongoing paid employment"
  );
}

export function formatPounds(amount: string | null): string {
  if (amount === null) return formatAmount(null);
  const unsigned = amount.replace(/^-/, "");
  const [whole, fraction = ""] = unsigned.split(".");
  return `${amount.startsWith("-") ? "−" : ""}£${formatAmount(`${whole}.${fraction.padEnd(2, "0")}`)}`;
}

export function summarizeMember(details: MemberDetails) {
  const pounds = details.summary.currencies.find(
    (group) => group.currency === "GBP",
  );
  const declarations = details.declarations.filter((declaration) =>
    isEarnings(declaration.categoryName),
  );
  const { months: earnings, undated } = registrationTimeline(declarations);
  return {
    total: pounds?.amount ?? null,
    firstRegisteredAt: details.summary.firstRegisteredAt,
    earningsTotals: {
      currentTerm: earningsTotal(
        declarations.filter(
          (declaration) =>
            declaration.registeredAt !== null &&
            Date.parse(declaration.registeredAt) >=
              Date.parse(CURRENT_PARLIAMENT_START),
        ),
      ),
      historical: earningsTotal(declarations),
    },
    categories: pounds?.categories ?? [],
    earnings,
    undated,
  };
}
<script lang="ts">
  import { page } from "$app/state";
  import { summarizeMember, formatPounds } from "./lib/member-summary";
  import Icon from "./lib/Icon.svelte";
  import { memberHref, type MemberProfile } from "./lib/entity-details";
  let {
    member,
    view,
    summary,
  }: {
    member: MemberProfile;
    view: "summary" | "history";
    summary: ReturnType<typeof summarizeMember>;
  } = $props();
  function dateLabel(value: string) {
    return new Date(value).toLocaleDateString("en-GB", {
      day: "numeric",
      month: "long",
      year: "numeric",
      timeZone: "UTC",
    });
  }
</script>

<header class="member-identity">
  <div class="member-identity-info">
    <div class="member-identity-title">
      <span class="profile-type"><Icon name="parliament" size={20} />MP</span>
      <h1>{member.name}</h1>
    </div>
    <p>
      {member.partyName || "Party unavailable"}<span
        >{member.membershipFrom || "Membership unavailable"}</span
      ><span>{member.isCurrentCommons ? "Current MP" : "Former MP"}</span>
    </p>
  </div>
  {#if view === "summary"}
    <div class="member-earnings-totals">
      <div class="earnings-values">
        <div class="member-value">
          <h2>Earnings this parliamentary term</h2>
          {#if summary.earningsTotals.currentTerm.declarationCount === 0}
            <p class="member-total unavailable">
              No declaration data available
            </p>
          {:else if summary.earningsTotals.currentTerm.amount === null}
            <p class="member-total unavailable">{formatPounds(null)}</p>
          {:else}
            <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard users need to scroll wide amounts without losing digits.) -->
            <div
              class="member-total"
              role="region"
              tabindex="0"
              aria-label="Earnings this parliamentary term in GBP"
              title={summary.earningsTotals.currentTerm.incomplete
                ? "Known GBP amounts only. Some amounts unavailable."
                : undefined}
            >
              {formatPounds(summary.earningsTotals.currentTerm.amount)}
            </div>
          {/if}
        </div>
        <div class="member-value">
          <h2>
            Historical earnings{summary.firstRegisteredAt
              ? ` since ${dateLabel(summary.firstRegisteredAt)}`
              : ""}
          </h2>
          {#if summary.earningsTotals.historical.declarationCount === 0}
            <p class="member-total unavailable">
              No declaration data available
            </p>
          {:else if summary.earningsTotals.historical.amount === null}
            <p class="member-total unavailable">{formatPounds(null)}</p>
          {:else}
            <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard users need to scroll wide amounts without losing digits.) -->
            <div
              class="member-total"
              role="region"
              tabindex="0"
              aria-label="Historical earnings in GBP"
              title={summary.earningsTotals.historical.incomplete
                ? "Known GBP amounts only. Some amounts unavailable."
                : undefined}
            >
              {formatPounds(summary.earningsTotals.historical.amount)}
            </div>
          {/if}
        </div>
      </div>
    </div>
  {/if}
  <nav class="member-tabs" aria-label="Member views">
    <a
      href={memberHref(member.id, "summary", page.url.searchParams)}
      aria-current={view === "summary" ? "page" : undefined}>Summary</a
    >
    <a
      href={memberHref(member.id, "history", page.url.searchParams)}
      aria-current={view === "history" ? "page" : undefined}
      >Declaration history</a
    >
  </nav>
</header>
  display: block;
}
